void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Time varying pixel color
    vec3 col = 0.5 + 0.5*cos(iTime+uv.xyx+vec3(0,2,4));

    // Output to screen
    fragColor = vec4(col,1.0);
}

const float C  = 261.63f;
const float D  = 293.66f;
const float E  = 329.63f;
const float F  = 349.23f;
const float G  = 392.00f;
const float A  = 440.00f;
const float B  = 493.88f;
const float C2 = 523.25f;

#define PI     3.141592653f
#define PI2    (PI * 2.0f)
#define REPEAT (8.0f)

float SoundTone(float hertz, float t)
{
    return sin(PI2 * hertz * t);
}

float SoundAmplitude(float t, float o)
{
    return t >= o ? exp(-4.0f * (t - o)) : 0.0f;
}

vec2 mainSound( int samp, float time )
{
    float t = mod(time * 1.2f, REPEAT);

    vec3 scores[] = vec3[](
        vec3(C, 0, 0),
        vec3(C, 0, 1),
        vec3(G, 1, 0),
        vec3(G, 1, 1),
        vec3(A, 2, 0),
        vec3(A, 2, 1),
        vec3(G, 3, 0),
        vec3(F, 4, 0),
        vec3(F, 4, 1),
        vec3(E, 5, 0),
        vec3(E, 5, 1),
        vec3(D, 6, 0),
        vec3(D, 6, 1),
        vec3(C, 7, 0)
    );

    float wave = 0.0f;
    for (int i = 0; i < scores.length(); ++i)
    {
        vec3 s = scores[i];
        wave += SoundTone(s.x, t) * SoundAmplitude(t, 1.0f * s.y + 0.5f * s.z);
    }

    return vec2(wave);
}
